der", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fee"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "More than 30 days before"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Free [confirm: deposit refunded?]"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 to 15 days before"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[X]% of the trek price"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "14 to 7 days before"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[X]% of the trek price"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Less than 7 days, or no-show"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[X]% of the trek price"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Changes by you"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You can change your dates, route or group size free of charge before departure, subject to availability. Extra costs, for example for extra days or permits, are charged at cost."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Changes and cancellation by us"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Mountain weather, landslides, closed trails or safety concerns can force changes. Your guide may change the route or turn back if continuing is unsafe. If we cancel before departure, you get a full refund of what you paid us."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Insurance, health and fitness"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Travel insurance that covers trekking at the altitudes of your trek and helicopter rescue is required. You confirm that you are fit enough for the trek you book and tell us about relevant health conditions."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Documents and permits"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "You need a passport valid for at least six months and a Nepal visa. We arrange your trekking permits; you provide passport copies and photos in time."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Our responsibility"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "We are responsible for providing the services in your confirmation with reasonable care. [LIABILITY TERMS, to be written by your lawyer.]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Complaints and applicable law"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Please tell your guide or our office straight away if something is wrong, so we can fix it on the spot. [APPLICABLE LAW AND COURT]."}]}]}, "lawyerChecked": false, "lastUpdated": "", "autoDate": true}$json$::jsonb
