-- Saves several pages in one transaction (as the admin, Row Level Security on): { "<slug>": the page as
-- save_site_page takes it }. Used by the editors that hold several pages (list pages, legal pages); replaces
-- save_list_pages.
create function public.save_site_pages(p_pages jsonb)
returns void
language plpgsql
set search_path = ''
as $$
declare
  page_slug text;
begin
  if jsonb_typeof(p_pages) <> 'object' then
    raise exception 'Pages must be an object' using errcode = '22023';
  end if;
  for page_slug in select jsonb_object_keys(p_pages) loop
    perform public.save_site_page(page_slug, p_pages -> page_slug, '[]'::jsonb);
  end loop;
end;
$$;

revoke all on function public.save_site_pages(jsonb) from public, anon;
grant execute on function public.save_site_pages(jsonb) to authenticated;

drop function public.save_list_pages(jsonb);
